import math, random
from itertools import combinations

def partitions(items, k):
    if k == 0:
        if not items:
            yield []
        return
    if not items:
        return
    first, rest = items[0], items[1:]
    for p in partitions(rest, k - 1):
        yield [[first]] + p
    for p in partitions(rest, k):
        for i in range(len(p)):
            yield p[:i] + [[first] + p[i]] + p[i + 1:]

def brute(points, k):
    best = -1.0
    for part in partitions(list(range(len(points))), k):
        spacing = min(math.dist(points[a], points[b])
                      for g1, g2 in combinations(part, 2) for a in g1 for b in g2)
        best = max(best, spacing)
    return best

